import Foundation

/// Arithmetic used only after the lesson has disclosed each probability and
/// horizon. It does not estimate a player's edge or prescribe a stake.
public enum CourseRiskMathError: Error, Equatable, Sendable { case invalidInput, nonFiniteResult }

public enum CourseRiskMath {
    /// Eventual absorption at zero for an i.i.d. ±1 random walk, p is the
    /// probability of +1 and capital is counted in equal units.
    public static func eventualRuinProbability(winProbability p: Double, capital: Int) throws -> Double {
        guard p.isFinite, (0...1).contains(p), capital >= 0 else { throw CourseRiskMathError.invalidInput }
        if capital == 0 || p <= 0.5 { return 1 }
        let value = pow((1 - p) / p, Double(capital))
        guard value.isFinite, (0...1).contains(value) else { throw CourseRiskMathError.nonFiniteResult }
        return value
    }

    /// P(hypothesis | signal), with likelihoods supplied by the caller.
    public static func posterior(prior: Double, signalGivenHypothesis: Double, signalGivenAlternative: Double) throws -> Double {
        guard [prior, signalGivenHypothesis, signalGivenAlternative].allSatisfy({ $0.isFinite && (0...1).contains($0) }) else {
            throw CourseRiskMathError.invalidInput
        }
        let numerator = prior * signalGivenHypothesis
        let denominator = numerator + (1 - prior) * signalGivenAlternative
        guard denominator > 0, denominator.isFinite else { throw CourseRiskMathError.invalidInput }
        let value = numerator / denominator
        guard value.isFinite else { throw CourseRiskMathError.nonFiniteResult }
        return value
    }

    public static func percentage(numerator: Double, denominator: Double) throws -> Double {
        guard numerator.isFinite, denominator.isFinite, numerator >= 0, denominator >= 1, numerator <= denominator, numerator.rounded() == numerator, denominator.rounded() == denominator else {
            throw CourseRiskMathError.invalidInput
        }
        return numerator / denominator * 100
    }
}

private func riskChoice(_ id: String, _ topic: CourseTopicID, _ title: String, _ purpose: FoundationPurpose,
                        _ context: [String], _ question: String, _ options: [String], _ correct: Int,
                        _ explanation: [String], _ error: String, _ term: String, _ definition: String,
                        _ example: String, _ method: String, _ assumptions: String, _ kind: LessonResultKind = .conditionalModel,
                        _ diagram: [FoundationDiagramRow], _ anchor: String) -> FoundationExercise {
    .init(id: id, topicID: topic, title: title, purpose: purpose, context: context, question: question,
          answer: .choice(options: options, correct: correct), explanation: explanation, typicalError: error,
          term: term, definition: definition, example: example, method: method, assumptions: assumptions,
          resultKind: kind, diagram: diagram, researchAnchor: anchor)
}

private func riskNumber(_ id: String, _ topic: CourseTopicID, _ title: String, _ purpose: FoundationPurpose,
                        _ context: [String], _ question: String, _ value: Double, _ tolerance: Double,
                        _ explanation: [String], _ error: String, _ term: String, _ definition: String,
                        _ example: String, _ method: String, _ assumptions: String, _ kind: LessonResultKind = .conditionalModel,
                        _ diagram: [FoundationDiagramRow], _ anchor: String) -> FoundationExercise {
    .init(id: id, topicID: topic, title: title, purpose: purpose, context: context, question: question,
          answer: .number(value: value, tolerance: tolerance), explanation: explanation, typicalError: error,
          term: term, definition: definition, example: example, method: method, assumptions: assumptions,
          resultKind: kind, diagram: diagram, researchAnchor: anchor)
}

